computationAlternatives.operation:
RoundAccounting(
{1- MaxValue(Discounts*/Discount Having
 (
  NoFieldFilled($Pricing/End,$Pricing/Start)  
  or ([Discounts/Start] >= [$Pricing/Start] and [Discounts/Start] <= [$Pricing/End])
  or ([Discounts/End] >= [$Pricing/Start] and [Discounts/End] <= [$Pricing/End]) 
  or ([Discounts/Start] < [$Pricing/Start] and 
        ([Discounts/End] >= [$Pricing/End] or FieldNotFilled(Discounts/End))
     )
  or ([Discounts/End] > [$Pricing/End] and 
        ([Discounts/Start] <= [$Pricing/Start] or FieldNotFilled(Discounts/Start))
     )   
 )
) / 100 
} * [Pricing/Price], 2)
